import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path
from typing import Iterable, Optional

import pandas as pd
import pytesseract
from PIL import Image, ImageOps


IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")


EXCLUSION_KEYWORDS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "TAX",
    "GST",
    "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

KEYWORD_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    [
        "TOTAL",
        "AMOUNT",
        "TOTAL DUE",
        "AMOUNT DUE",
        "BALANCE DUE",
        "NETT TOTAL",
        "NET TOTAL",
    ],
]


_AMOUNT_TOKEN_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,4})?(?!\d)")
_CURRENCY_AMOUNT_RE = re.compile(
    r"(?:\bRM\b|\bMYR\b|\bUSD\b|\$)\s*([0-9][0-9,]*(?:\.[0-9]{1,4})?)",
    re.IGNORECASE,
)


MONTHS = {
    "JAN": 1,
    "JANUARY": 1,
    "FEB": 2,
    "FEBRUARY": 2,
    "MAR": 3,
    "MARCH": 3,
    "APR": 4,
    "APRIL": 4,
    "MAY": 5,
    "JUN": 6,
    "JUNE": 6,
    "JUL": 7,
    "JULY": 7,
    "AUG": 8,
    "AUGUST": 8,
    "SEP": 9,
    "SEPT": 9,
    "SEPTEMBER": 9,
    "OCT": 10,
    "OCTOBER": 10,
    "NOV": 11,
    "NOVEMBER": 11,
    "DEC": 12,
    "DECEMBER": 12,
}


def _safe_date(y: int, m: int, d: int) -> Optional[date]:
    try:
        return date(y, m, d)
    except ValueError:
        return None


def _normalize_year(y: int) -> int:
    if y < 100:
        return 2000 + y
    return y


def extract_date(text: str) -> Optional[str]:
    t = text

    # YYYY-MM-DD / YYYY/MM/DD
    for m in re.finditer(r"\b(20\d{2})[\-/\.](\d{1,2})[\-/\.](\d{1,2})\b", t):
        y, mo, d = map(int, m.groups())
        dt = _safe_date(y, mo, d)
        if dt:
            return dt.isoformat()

    # DD-MM-YYYY or DD/MM/YY (assume day-first when ambiguous)
    for m in re.finditer(r"\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})\b", t):
        a, b, y = m.groups()
        d1, m1, y1 = int(a), int(b), _normalize_year(int(y))

        # Heuristic: if one side > 12, it must be day.
        if d1 > 12:
            dt = _safe_date(y1, m1, d1)
        elif m1 > 12:
            dt = _safe_date(y1, d1, m1)
        else:
            dt = _safe_date(y1, m1, d1)

        if dt:
            return dt.isoformat()

    # Month name formats: 29 DEC 2017, 29-DEC-2017, DEC 29 2017
    month_pat = "|".join(sorted(MONTHS.keys(), key=len, reverse=True))

    for m in re.finditer(
        rf"\b(\d{{1,2}})\s*[\-/\.]?\s*({month_pat})\s*[\-/\.]?\s*(\d{{2,4}})\b",
        t,
        flags=re.IGNORECASE,
    ):
        d_s, mon_s, y_s = m.groups()
        dt = _safe_date(_normalize_year(int(y_s)), MONTHS[mon_s.upper()], int(d_s))
        if dt:
            return dt.isoformat()

    for m in re.finditer(
        rf"\b({month_pat})\s*(\d{{1,2}})\s*,?\s*(\d{{2,4}})\b",
        t,
        flags=re.IGNORECASE,
    ):
        mon_s, d_s, y_s = m.groups()
        dt = _safe_date(_normalize_year(int(y_s)), MONTHS[mon_s.upper()], int(d_s))
        if dt:
            return dt.isoformat()

    return None


def _to_money_str(token: ***REDACTED*** -> Optional[str]:
    token = ***REDACTED***",", "").strip()
    if not token:
        return None
    try:
        val = Decimal(token)
    except InvalidOperation:
        return None

    val = val.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    # Always output exactly two decimals
    return f"{val:.2f}"


def _best_amount_from_line(line: str) -> Optional[str]:
    # Prefer currency-tagged amounts first
    cur = _CURRENCY_AMOUNT_RE.findall(line)
    if cur:
        out = _to_money_str(cur[-1])
        if out is not None:
            return out

    tokens = _AMOUNT_TOKEN_RE.findall(line)
    if not tokens:
        return None

    # Prefer last token with a decimal point; else last token.
    decimal_tokens = [t for t in tokens if "." in t]
    chosen = (decimal_tokens[-1] if decimal_tokens else tokens[-1]).strip()
    return _to_money_str(chosen)


def extract_total_amount(text: str) -> Optional[str]:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]

    def is_excluded(ln_u: str) -> bool:
        return any(k in ln_u for k in EXCLUSION_KEYWORDS)

    def find(allow_excluded: bool) -> Optional[str]:
        for group in KEYWORD_GROUPS:
            for i, ln in enumerate(lines):
                ln_u = ln.upper()
                if not any(k in ln_u for k in group):
                    continue
                if (not allow_excluded) and is_excluded(ln_u):
                    continue

                amt = _best_amount_from_line(ln)
                if amt is not None:
                    return amt

                # Fallback: next-line amount
                if i + 1 < len(lines):
                    nxt = lines[i + 1].strip()
                    nxt_u = nxt.upper()
                    if (not allow_excluded) and is_excluded(nxt_u):
                        continue
                    amt2 = _best_amount_from_line(nxt)
                    if amt2 is not None:
                        return amt2
        return None

    return find(allow_excluded=False) or find(allow_excluded=True)


@dataclass
class OcrAttempt:
    text: str
    mean_conf: float


def _mean_conf_from_data(data: dict) -> float:
    confs = []
    for c in data.get("conf", []):
        try:
            v = float(c)
        except Exception:
            continue
        if v > 0:
            confs.append(v)
    if not confs:
        return 0.0
    return sum(confs) / len(confs)


def ocr_best_text(img_path: Path) -> str:
    img = Image.open(img_path)
    base = ImageOps.autocontrast(ImageOps.grayscale(img))

    variants = [
        base,
        base.resize((base.width * 2, base.height * 2)),
        base.point(lambda p: 255 if p > 180 else 0),
        ImageOps.invert(base),
    ]

    attempts: list[OcrAttempt] = []
    config = "--oem 3 --psm 6"

    for v in variants:
        try:
            data = pytesseract.image_to_data(v, output_type=pytesseract.Output.DICT, config=config)
            txt = pytesseract.image_to_string(v, config=config)
            attempts.append(OcrAttempt(text=txt, mean_conf=_mean_conf_from_data(data)))
        except Exception:
            continue

    if not attempts:
        return ""

    best = max(attempts, key=lambda a: (a.mean_conf, len(a.text)))
    return best.text


def main() -> None:
    img_paths: list[Path] = []
    for ext in ("*.jpg", "*.jpeg", "*.png", "*.webp"):
        img_paths.extend(IMG_DIR.glob(ext))
    img_paths = sorted({p.resolve() for p in img_paths}, key=lambda p: p.name)

    rows = []
    for p in img_paths:
        text = ocr_best_text(p)
        dt = extract_date(text)
        total = extract_total_amount(text)
        rows.append({"filename": p.name, "date": dt, "total_amount": total})

    df = pd.DataFrame(rows, columns=["filename", "date", "total_amount"])

    OUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
    df.to_excel(OUT_XLSX, index=False, sheet_name="results")

    # Post-write validation (schema + only one sheet)
    check = pd.read_excel(OUT_XLSX, sheet_name="results")
    if list(check.columns) != ["filename", "date", "total_amount"]:
        raise SystemExit(f"Unexpected columns: {list(check.columns)}")


if __name__ == "__main__":
    main()
